INSERT INTO public.events (title, start_date, end_date, start_time, end_time, category, location, description, coach, registration_deadline, entry_fee, travel_info, weight_classes, rsvp_required, external_link, logo_url, drop_in_registration_link, max_drop_ins, created_at, updated_at)
VALUES ('Rock Hill Bearcat Invitational', '2025-07-20'::date, NULL, NULL, NULL, 'national-tournament', 'Rock Hill High School, 320 W Springdale Rd, Rock Hill, SC.', 'Rock Hill Bearcat Invitational – High School Wrestling Tournament
The Bearcat Invitational, hosted annually by Rock Hill High School in Rock Hill, South Carolina, is one of the Southeast’s premier in-season high school wrestling tournaments. Held just south of Charlotte, the event consistently draws top teams from across North Carolina, South Carolina, and neighboring states.

📅 2026 Tentative Dates: January 3–4, 2026

📍 Location: Rock Hill High School, Rock Hill, SC

🎯 Format: Individual bracketed tournament with boys and girls divisions

🔥 Competition Highlights
Features a deep field of 40+ high school programs, including multiple state-ranked athletes

Offers early-season, high-level competition that helps wrestlers and teams prepare for postseason success

Well-run two-day format with multiple matches guaranteed and team scoring implications

✅ Participation Details
Open to high school teams by invitation or registration approval

Wrestlers must compete as part of an official school team

Sanctioned and listed on official SC and regional wrestling calendars', NULL, NULL, NULL, NULL, NULL, false, NULL, NULL, NULL, 10, '2025-07-20T19:52:18+00:00'::timestamptz, NOW());

INSERT INTO public.events (title, start_date, end_date, start_time, end_time, category, location, description, coach, registration_deadline, entry_fee, travel_info, weight_classes, rsvp_required, external_link, logo_url, drop_in_registration_link, max_drop_ins, created_at, updated_at)
VALUES ('Knock Out', '2025-07-20'::date, NULL, NULL, NULL, 'national-tournament', NULL, '🏆 Knockout Christmas Classic – High School Wrestling Tournament
The Knockout Christmas Classic is one of the premier in-season high school wrestling tournaments in the country, held annually at the Silver Spurs Arena in Kissimmee, Florida. This elite-level competition attracts top programs from across the Southeast and beyond.

🔹 Tournament Details
Dates: December 19–20, 2025

Location: Silver Spurs Arena, Kissimmee, FL

Divisions: High School Boys & Girls (no open or individual entries)

🔒 Participation Requirements
High School Team Entry Only – Wrestlers must compete as part of an officially recognized high school program.

Official School Schedule – Participation must be approved by your school’s athletic director or administration and included on the official competition schedule.

Tournament Approval – All teams must be approved by Knockout tournament staff following registration. Entry is limited and highly competitive.

AAU Membership Required – All wrestlers and coaches must have valid AAU cards prior to the event.

No Unattached or Club Entries – Independent or club wrestlers are not permitted. This is strictly a high school team event.', NULL, NULL, NULL, NULL, NULL, false, NULL, 'https://w8v0puzioqkz0xzh.public.blob.vercel-storage.com/event-logos/1753039646570.jpeg', NULL, 10, '2025-07-20T19:27:26+00:00'::timestamptz, NOW());

