VALUES ('Ultimate Club Duals', '2025-07-11'::date, NULL, NULL, NULL, 'ncu-dual-tournament', 'Nittany Valley Sports Centre 177 Champion Dr, State College, PA', 'NC United National Team returns to State College, PA for the Ultimate Club Duals! After an impressive showing as Gold Pool finalists in last year''s inaugural event, we''re back with unfinished business — eyes set on bringing home Gold in the Gold. Let''s go NC! 💪🥇', NULL, NULL, NULL, NULL, NULL, false, NULL, 'https://w8v0puzioqkz0xzh.public.blob.vercel-storage.com/event-logos/1752373334500.png', NULL, 10, '2025-07-11T15:39:28+00:00'::timestamptz, NOW());

