INSERT INTO public.events (title, start_date, end_date, start_time, end_time, category, location, description, coach, registration_deadline, entry_fee, travel_info, weight_classes, rsvp_required, external_link, logo_url, drop_in_registration_link, max_drop_ins, created_at, updated_at)
VALUES ('Beast of The East', '2025-07-20'::date, NULL, NULL, NULL, 'national-tournament', NULL, '🐯 Beast of the East Wrestling Tournament  is one of the premier in-season high school folkstyle tournaments in the U.S., held annually at the Bob Carpenter Center, University of Delaware. 

Dates for December 2025:

Girls'' Beast of the East – December 18–19, 2025

Boys'' Beast of the East – December 20–21, 2025 

The Beast of the East is for high school teams only, requiring admin approval and application via school officials.

Applications typically open in summer/fall—the 2025 Boys'' application closed, Girls'' is open now. 
beastwrestling.com

Weigh-ins and brackets happen on-site; it’s a two-day, elite tournament at Delaware’s Bob Carpenter Center with rigorous competition and team scoring.', NULL, NULL, NULL, NULL, NULL, false, NULL, 'https://w8v0puzioqkz0xzh.public.blob.vercel-storage.com/event-logos/1753039149088.png', NULL, 10, '2025-07-20T19:19:09+00:00'::timestamptz, NOW());

INSERT INTO public.events (title, start_date, end_date, start_time, end_time, category, location, description, coach, registration_deadline, entry_fee, travel_info, weight_classes, rsvp_required, external_link, logo_url, drop_in_registration_link, max_drop_ins, created_at, updated_at)
VALUES ('Journeymen', '2025-07-11'::date, NULL, NULL, NULL, 'national-tournament', 'Schenectady, NY', '🏆 Journeymen Fall Classic – Preseason Elite Wrestling Event
The Journeymen Fall Classic is one of the most competitive preseason wrestling tournaments in the U.S., held each October at Union College in Schenectady, NY. It features top-ranked high school, middle school, and youth wrestlers from across the country.

📅 2025 Dates: October 4–5, 2025

📍 Location: Union College Field House, Schenectady, NY

🎯 Format: Modified round-robin (3–5 matches per athlete)

📺 Coverage: Live and archived on FloWrestling

🔒 Entry Requirements
Coach or club nomination only

Wrestlers must be entered by a recognized coach or club leader

No walk-ups or individual entries; selection is based on credentials (state placers, nationally ranked, etc.)

Limited spots; early entry is strongly encouraged

📝 Apply or Request Entry
Application Page: www.journeymenwrestling.com

Or contact the director via email: info@journeymenwrestling.com', NULL, NULL, NULL, NULL, NULL, false, NULL, NULL, NULL, 10, '2025-07-11T15:44:26+00:00'::timestamptz, NOW());

INSERT INTO public.events (title, start_date, end_date, start_time, end_time, category, location, description, coach, registration_deadline, entry_fee, travel_info, weight_classes, rsvp_required, external_link, logo_url, drop_in_registration_link, max_drop_ins, created_at, updated_at)
VALUES ('Escape The Rock', '2025-07-20'::date, NULL, NULL, NULL, 'national-tournament', 'Council Rock South High School, Holland, PA 18966', '🧗‍♂️ 2026 Escape the Rock – High School Wrestling Tournament

The Escape the Rock is one of the premier in-season individual high school wrestling tournaments in the country. It draws top-ranked wrestlers and powerhouse programs from across the U.S. for a highly competitive two-day event.

📅 Dates: January 17–18, 2026

📍 Location: Council Rock South High School, Holland, PA

🏆 Format: Individual bracketed tournament

🎯 Eligibility: High school athletes only — must be entered through their school’s official wrestling program

🆕 Girls Division: Added for 2026

🔒 Entry Requirements
Wrestlers must be entered by their high school coach or athletic department

Tournament participation must be on the official school schedule

All entries are subject to approval by Escape the Rock staff

No unattached or club entries permitted', NULL, NULL, NULL, NULL, NULL, false, NULL, NULL, NULL, 10, '2025-07-20T19:36:11+00:00'::timestamptz, NOW());

